def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))

            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            area = (y1 - y0 + 1) * (x1 - x0 + 1)
            if area >= 4 and len(cells) >= area * 0.4:
                for y in range(y0, y1 + 1):
                    for x in range(x0, x1 + 1):
                        out[y][x] = color
    return out
